def solve(task, store, threshold=0.80):
    hit = store.search(task.text, k=1)[0]
    if hit.score >= threshold:
        plan = hit.item.steps
    else:
        plan = agent.explore(task)
    result = agent.follow(plan)
    store.record(task, result.steps)      # save for future reuse
    return result
